    /// <summary>
    /// COC method
    /// </summary>
    /// <param name = "_parmLine">ParmLine buffer</param>
    /// <returns>whether to create parmLine or not</returns>
    public boolean shouldCreateParmLine(FormletterParmLine _parmLine)
    {
        boolean ret = next shouldCreateParmLine(_parmLine);
        METCustParameters METCustParameters = METCustParameters::Find();

        if (_parmLine.TableId == tableNum(SalesParmLine) &&
            //CB175_SalesConfirmation - start
            (METCustParameters.IncludeCancelledLines))
            //CB175_SalesConfirmation - end
        {
            ret = true;
        }
        return ret;
    }
